INVENTARIOS_SCHEDULER_PRINCIPAL_CODE = "SYS-SCHED-INVENTARIOS"
INVENTARIOS_SCHEDULER_PERMISSION_CODE = "inventarios_EJECUTAR"


def _resolve_system_principal_empresa_uuids(usuario_id: int) -> list[str]:
    """Proyecta el scope SQL canónico del principal al contrato legacy de reportes."""
    from core.rbac_sql.service import RBACSQLService

    company_rows = RBACSQLService.get_empresas(usuario_id) or []
    company_ids = sorted({
        int(row["EmpresaID"])
        for row in company_rows
        if row.get("EmpresaID") is not None
    })

    if not company_ids:
        return []

    placeholders = ", ".join(["%s"] * len(company_ids))

    with get_sql_connection() as conn:
        cur = conn.cursor()
        cur.execute(
            f"""
            SELECT EmpresaMongoUUID
            FROM dbo.Sistema_EmpresasMongoMap
            WHERE EmpresaID_SQL IN ({placeholders})
              AND EmpresaMongoUUID IS NOT NULL
            ORDER BY EmpresaID_SQL
            """,
            tuple(company_ids),
        )
        rows = cur.fetchall()

    return [str(row[0]) for row in rows if row and row[0]]


def resolve_inventarios_scheduler_current_user() -> Dict:
    """Identidad técnica canónica de mínimo privilegio para Inventarios."""
    from core.rbac_sql.service import RBACSQLService

    current_user = resolve_system_principal_current_user(
        INVENTARIOS_SCHEDULER_PRINCIPAL_CODE
    )
    usuario_id = int(current_user["UsuarioID"])

    if not RBACSQLService.can_access_permission(
        usuario_id,
        INVENTARIOS_SCHEDULER_PERMISSION_CODE,
    ):
        raise SystemPrincipalResolutionError(
            "Principal técnico de Inventarios sin permiso inventarios:EJECUTAR"
        )

    empresas_permitidas = _resolve_system_principal_empresa_uuids(
        usuario_id
    )
    if not empresas_permitidas:
        raise SystemPrincipalResolutionError(
            "Principal técnico de Inventarios sin scope empresarial efectivo"
        )

    return {
        **current_user,
        "empresas_permitidas": empresas_permitidas,
    }

