/*
EDARSAHUB V1.0
Rollback quirurgico del principal tecnico Scheduler / Inventarios.
No elimina catalogos compartidos de modulos/acciones.
*/

SET NOCOUNT ON;
SET XACT_ABORT ON;

BEGIN TRY
    BEGIN TRANSACTION;

    DECLARE @UsuarioID INT;
    DECLARE @RolID INT;

    SELECT @UsuarioID = UsuarioID
    FROM dbo.Usuario_Catalogo
    WHERE UPPER(LTRIM(RTRIM(ISNULL(CodigoUsuario,'')))) = 'SYS-SCHED-INVENTARIOS'
      AND UPPER(LTRIM(RTRIM(ISNULL(Username,'')))) = 'SYS-SCHED-INVENTARIOS'
      AND ISNULL(EsUsuarioPortal,1) = 0
      AND ISNULL(Bloqueado,0) = 1;

    SELECT @RolID = RolID
    FROM dbo.Usuario_Roles
    WHERE UPPER(LTRIM(RTRIM(ISNULL(CodigoRol,'')))) = 'SCHEDULER_INVENTARIOS';

    IF @UsuarioID IS NOT NULL
    BEGIN
        DELETE FROM dbo.Usuario_SucursalesAsignacion
        WHERE UsuarioID = @UsuarioID;

        DELETE FROM dbo.Usuario_ServidoresAsignacion
        WHERE UsuarioID = @UsuarioID;

        DELETE FROM dbo.Usuario_EmpresasAsignacion
        WHERE UsuarioID = @UsuarioID;

        DELETE FROM dbo.Usuario_RolesAsignacion
        WHERE UsuarioID = @UsuarioID
          AND (@RolID IS NULL OR RolID = @RolID);

        DELETE FROM dbo.Usuario_Catalogo
        WHERE UsuarioID = @UsuarioID
          AND UPPER(LTRIM(RTRIM(ISNULL(CodigoUsuario,'')))) = 'SYS-SCHED-INVENTARIOS'
          AND UPPER(LTRIM(RTRIM(ISNULL(Username,'')))) = 'SYS-SCHED-INVENTARIOS'
          AND ISNULL(EsUsuarioPortal,1) = 0
          AND ISNULL(Bloqueado,0) = 1;
    END;

    IF @RolID IS NOT NULL
    BEGIN
        DELETE FROM dbo.Usuario_PermisosRolModulo
        WHERE RolID = @RolID;

        IF NOT EXISTS (
            SELECT 1
            FROM dbo.Usuario_RolesAsignacion
            WHERE RolID = @RolID
        )
        BEGIN
            DELETE FROM dbo.Usuario_Roles
            WHERE RolID = @RolID
              AND UPPER(LTRIM(RTRIM(ISNULL(CodigoRol,'')))) = 'SCHEDULER_INVENTARIOS';
        END;
    END;

    COMMIT TRANSACTION;

    SELECT 'PASS' AS Resultado;

END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION;
    THROW;
END CATCH;
